(function(){
  var LOGO = 'data:image/png;base64,';
  var APP_ICON = 'data:image/png;base64,';
  function applyIcons(){
    document.querySelectorAll('img.brand-logo').forEach(function(el){ el.src = LOGO; });
    document.querySelectorAll('link[rel="icon"],link[rel="apple-touch-icon"]').forEach(function(l){ l.href = APP_ICON; });
  }
  if(document.readyState === 'loading'){ document.addEventListener('DOMContentLoaded', applyIcons); } else { applyIcons(); }
})();